// Fails when the migrated database and the Prisma schema differ, except for indexes Prisma
// cannot express (created by hand in migrations). New migrations generated by
// `prisma migrate dev` will propose dropping these; delete those lines before applying.
import { execFileSync } from 'node:child_process';

const RAW_INDEXES = ['ContentChunk_embedding_hnsw_idx'];

const sql = execFileSync(
  'prisma',
  ['migrate', 'diff', '--from-config-datasource', '--to-schema', 'prisma/schema', '--script'],
  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'] },
);
const statements = sql
  .split(';')
  .map((s) => s.replace(/^\s*--.*$/gm, '').trim())
  .filter(Boolean)
  .filter((s) => !RAW_INDEXES.some((name) => s === `DROP INDEX "${name}"`));
if (statements.length) {
  console.error('Schema drift between migrations and prisma/schema:\n');
  console.error(statements.join(';\n\n'));
  process.exit(2);
}
console.log('No schema drift.');
